class Solution:
    def beautifulIndices(self, s, a, b, k):
        def zfunc(t):
            z = [0] * len(t)
            l = r = 0
            for i in range(1, len(t)):
                if i < r:
                    z[i] = min(r - i, z[i - l])
                while i + z[i] < len(t) and t[z[i]] == t[i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l, r = i, i + z[i]
            return z
        za = zfunc(a + '#' + s)
        zb = zfunc(b + '#' + s)
        la, lb = len(a), len(b)
        A = [i - la - 1 for i in range(la + 1, len(za)) if za[i] == la]
        B = [i - lb - 1 for i in range(lb + 1, len(zb)) if zb[i] == lb]
        import bisect
        res = []
        for i in A:
            p = bisect.bisect_left(B, i - k)
            if p < len(B) and B[p] <= i + k:
                res.append(i)
        return res

