class Solution {
    vector<int> zfunc(const string& t) {
        int n = t.size();
        vector<int> z(n, 0);
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = min(r - i, z[i - l]);
            while (i + z[i] < n && t[z[i]] == t[i + z[i]]) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    }
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        auto za = zfunc(a + "#" + s);
        auto zb = zfunc(b + "#" + s);
        vector<int> A, B, res;
        for (int i = a.size() + 1; i < (int)za.size(); i++)
            if (za[i] == (int)a.size()) A.push_back(i - a.size() - 1);
        for (int i = b.size() + 1; i < (int)zb.size(); i++)
            if (zb[i] == (int)b.size()) B.push_back(i - b.size() - 1);
        for (int i : A) {
            auto it = lower_bound(B.begin(), B.end(), i - k);
            if (it != B.end() && *it <= i + k) res.push_back(i);
        }
        return res;
    }
};

