class Solution {
    private int[] zfunc(String t) {
        int n = t.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < n && t.charAt(z[i]) == t.charAt(i + z[i])) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    }
    public List<Integer> beautifulIndices(String s, String a, String b, int k) {
        int[] za = zfunc(a + "#" + s);
        int[] zb = zfunc(b + "#" + s);
        List<Integer> A = new ArrayList<>(), B = new ArrayList<>(), res = new ArrayList<>();
        for (int i = a.length() + 1; i < za.length; i++)
            if (za[i] == a.length()) A.add(i - a.length() - 1);
        for (int i = b.length() + 1; i < zb.length; i++)
            if (zb[i] == b.length()) B.add(i - b.length() - 1);
        for (int i : A) {
            int p = Collections.binarySearch(B, i - k);
            int idx = (p >= 0) ? p : -(p + 1);
            if (idx < B.size() && B.get(idx) <= i + k) res.add(i);
        }
        return res;
    }
}

