var beautifulIndices = function(s, a, b, k) {
    const zfunc = (t) => {
        const z = new Array(t.length).fill(0);
        let l = 0, r = 0;
        for (let i = 1; i < t.length; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < t.length && t[z[i]] === t[i + z[i]]) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    };
    const za = zfunc(a + "#" + s), zb = zfunc(b + "#" + s);
    const A = [], B = [];
    for (let i = a.length + 1; i < za.length; i++)
        if (za[i] === a.length) A.push(i - a.length - 1);
    for (let i = b.length + 1; i < zb.length; i++)
        if (zb[i] === b.length) B.push(i - b.length - 1);
    const res = [];
    for (const i of A) {
        let lo = 0, hi = B.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (B[mid] < i - k) lo = mid + 1; else hi = mid; }
        if (lo < B.length && B[lo] <= i + k) res.push(i);
    }
    return res;
};
